// Sara customer portal: email sign-in codes, sessions and access checks.
// Codes and sessions are kept only as SHA-256 hashes in this workflow's static data.
const req = $('Portal Webhook').first().json;
const body = req.body || {};
const h = req.headers || {};
const ip = String(h['cf-connecting-ip'] || h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || 'unknown').trim();
const action = String(body.action || '').trim();
const email = String(body.email || '').trim().toLowerCase().slice(0, 160);
const crypto = require('crypto');
const sha = function (s) { return crypto.createHash('sha256').update(String(s)).digest('hex'); };
const digits = function (v) { return String(v == null ? '' : v).replace(/\D/g, ''); };
const sd = $getWorkflowStaticData('global');
sd.codes = sd.codes || {};
sd.sessions = sd.sessions || {};
const now = Date.now();
Object.keys(sd.codes).forEach(function (k) { if (sd.codes[k].exp < now) delete sd.codes[k]; });
Object.keys(sd.sessions).forEach(function (k) { if (sd.sessions[k].exp < now) delete sd.sessions[k]; });
const hour = Math.floor(now / 3600000);
if (!sd.rate || sd.rate.hour !== hour) sd.rate = { hour: hour, ip: {}, email: {}, data: {} };

function out(next, extra) { return [{ json: Object.assign({ next: next }, extra) }]; }
function reply(status, payload) { return out('respond', { status: status, body: payload }); }
const accounts = $input.all().map(function (i) { return i.json; })
  .filter(function (a) { return a && a.email && (a.active === true || String(a.active).toLowerCase() === 'true'); });
function findAccount(e, phone) {
  return accounts.find(function (a) {
    return String(a.email).trim().toLowerCase() === e && (phone === undefined || digits(a.client_phone) === phone);
  });
}

if (action === 'request_code') {
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return reply(400, { ok: false, error: 'bad_email' });
  sd.rate.ip[ip] = (sd.rate.ip[ip] || 0) + 1;
  sd.rate.email[email] = (sd.rate.email[email] || 0) + 1;
  if (sd.rate.ip[ip] > 20 || sd.rate.email[email] > 5) return reply(429, { ok: false, error: 'too_many' });
  const acct = findAccount(email);
  // Same answer whether or not the email has an account, so nobody can probe for customers.
  if (!acct) return reply(200, { ok: true });
  const code = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
  sd.codes[email] = { hash: sha(email + ':' + code), exp: now + 10 * 60000, tries: 0 };
  return out('send_code', { email: email, code: code, business: acct.business_name || 'your business' });
}

if (action === 'verify') {
  const code = String(body.code || '').replace(/\D/g, '');
  const rec = sd.codes[email];
  if (!rec) return reply(401, { ok: false, error: 'expired' });
  rec.tries = (rec.tries || 0) + 1;
  if (rec.tries > 5) { delete sd.codes[email]; return reply(429, { ok: false, error: 'too_many' }); }
  if (sha(email + ':' + code) !== rec.hash) return reply(401, { ok: false, error: 'wrong_code' });
  delete sd.codes[email];
  const acct = findAccount(email);
  if (!acct) return reply(401, { ok: false, error: 'no_account' });
  const token = crypto.randomBytes(32).toString('hex');
  sd.sessions[sha(token)] = { email: email, client_phone: digits(acct.client_phone), sheet_id: String(acct.sheet_id || ''), business: acct.business_name || '', exp: now + 30 * 86400000 };
  return reply(200, { ok: true, token: token, business: acct.business_name || '', email: email });
}

if (action === 'data' || action === 'sign_out' || action === 'set_status') {
  const token = String(body.token || '');
  const key = /^[a-f0-9]{64}$/.test(token) ? sha(token) : '';
  const s = key ? sd.sessions[key] : null;
  if (!s) return reply(401, { ok: false, error: 'signed_out' });
  if (action === 'sign_out') { delete sd.sessions[key]; return reply(200, { ok: true }); }
  // An account switched off in the table loses access straight away.
  if (!findAccount(s.email, s.client_phone)) { delete sd.sessions[key]; return reply(401, { ok: false, error: 'signed_out' }); }
  sd.rate.data[key] = (sd.rate.data[key] || 0) + 1;
  if (sd.rate.data[key] > 300) return reply(429, { ok: false, error: 'too_many' });
  const result = { client_phone: s.client_phone, sheet_id: s.sheet_id || '', business: s.business, email: s.email };
  if (action === 'set_status') {
    // Only the status cell of a row in the signed-in business's own sheet can change, and only to these values.
    const TABS = { appointment: 'Appointments', ticket: 'Tickets', transfer: 'Transfers', callback: 'Call Backs' };
    const ALLOWED = { appointment: ['completed', 'booked'], ticket: ['resolved', 'open'], transfer: ['done', 'pending'], callback: ['done', 'pending'] };
    const type = String(body.type || '');
    const row = parseInt(body.row, 10);
    const status = String(body.status || '').toLowerCase();
    if (!TABS[type] || !(row >= 2 && row < 100000) || ALLOWED[type].indexOf(status) < 0) return reply(400, { ok: false, error: 'bad_update' });
    result.update = { tab: TABS[type], row: row, status: status };
  }
  return out('read_data', result);
}

return reply(400, { ok: false, error: 'bad_action' });

// Finds this business's own sheet: stored on its account (self-serve sign-ups),
// otherwise looked up by its Sara phone number in the Client Config Master.
const who = $('Handle Request').first().json;
if (who.sheet_id) return [{ json: { sheet_id: String(who.sheet_id), client_name: who.business || '' } }];
const want = who.client_phone;
const digits = function (v) { return String(v == null ? '' : v).replace(/\D/g, ''); };
const row = want ? $input.all().map(function (i) { return i.json; }).find(function (r) { return digits(r.phone_number) === want; }) : null;
return [{ json: { sheet_id: row && row.sheet_id ? String(row.sheet_id) : 'missing', client_name: row ? (row.client_name || '') : '' } }];

// Turns the business's sheet tabs into one activity feed plus headline numbers.
const who = $('Handle Request').first().json;
function rows(name) {
  try { return $(name).all().map(function (i) { return i.json; }).filter(function (r) { return r && !r.error && Object.keys(r).filter(function (k) { return k !== 'row_number'; }).length > 0; }); }
  catch (e) { return []; }
}
function txt(v) { if (v === undefined || v === null) return ''; const s = String(v).trim(); return s.indexOf('#ERROR') === 0 ? '' : s; }
// Sheets can return dates as serial numbers (days since 1899-12-30) or as text.
function toTime(v) {
  if (v === undefined || v === null || v === '') return NaN;
  if (typeof v === 'number') return Math.round((v - 25569) * 86400000);
  const s = String(v).trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?\s*(AM|PM)?\s*(Z|[+-]\d{2}:?\d{2})?)?$/i);
  if (m) {
    let hh = m[4] ? parseInt(m[4], 10) : 0;
    if (m[7]) { const pm = m[7].toUpperCase() === 'PM'; if (pm && hh < 12) hh += 12; if (!pm && hh === 12) hh = 0; }
    const iso = m[1] + '-' + m[2] + '-' + m[3] + 'T' + String(hh).padStart(2, '0') + ':' + (m[5] || '00') + ':' + (m[6] || '00') + (m[8] ? m[8] : '');
    return Date.parse(iso);
  }
  return Date.parse(s);
}
function iso(t) { return isNaN(t) ? '' : new Date(t).toISOString(); }
// Spreadsheet date numbers carry the business's own wall-clock time, so show them as written.
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function wallText(v) {
  if (typeof v !== 'number') return txt(v);
  const d = new Date(Math.round((v - 25569) * 86400000));
  let h = d.getUTCHours(); const m = d.getUTCMinutes(); const ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  const time = (d.getUTCHours() === 0 && m === 0) ? '' : ', ' + h + ':' + String(m).padStart(2, '0') + ' ' + ap;
  return DAYS[d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear() + time;
}
const examples = ['APT-0001', 'TIX-0001'];
const activity = [];

rows('Read Appointments').forEach(function (r) {
  const id = txt(r.id);
  if (examples.indexOf(id) >= 0 || id.indexOf('Legend') === 0) return;
  const at = toTime(r.created_at);
  if (isNaN(at)) return;
  const when = toTime(r.datetime);
  activity.push({ row: r.row_number, id: id || ('appt-' + at), type: 'appointment', name: txt(r.customer_name), phone: txt(r.phone),
    detail: txt(r.service) || 'Appointment', when: isNaN(when) ? txt(r.datetime) : iso(when), when_text: wallText(r.datetime),
    status: (txt(r.status) || 'booked').toLowerCase(), at: iso(at) });
});
rows('Read Tickets').forEach(function (r) {
  const id = txt(r.ticket_id) || txt(r.id);
  if (examples.indexOf(id) >= 0 || id.indexOf('Legend') === 0) return;
  const at = toTime(r.created_at);
  if (isNaN(at)) return;
  activity.push({ row: r.row_number, id: id || ('ticket-' + at), type: 'ticket', name: txt(r.customer_name), phone: txt(r.phone_number) || txt(r.phone),
    detail: txt(r.issue_description) || txt(r.issue) || 'Support ticket', priority: txt(r.priority).toLowerCase(),
    status: (txt(r.status) || 'open').toLowerCase(), at: iso(at) });
});
rows('Read Transfers').forEach(function (r) {
  const at = toTime(r.timestamp);
  if (isNaN(at)) return;
  activity.push({ row: r.row_number, id: 'transfer-' + at, type: 'transfer', name: txt(r.customer_name), phone: txt(r.caller_phone),
    detail: txt(r.reason) || 'Transfer requested', department: txt(r.department), status: (txt(r.status) || 'pending').toLowerCase(), at: iso(at) });
});
rows('Read Call Backs').forEach(function (r) {
  const at = toTime(r.timestamp);
  if (isNaN(at)) return;
  activity.push({ row: r.row_number, id: 'callback-' + at, type: 'callback', name: txt(r.customer_name), phone: txt(r.caller_phone),
    detail: txt(r.notes) || 'Callback requested', when_text: wallText(r.callback_time), status: (txt(r.status) || 'pending').toLowerCase(), at: iso(at) });
});

const seen = {};
const feed = activity.filter(function (a) { const k = a.type + a.id + a.at; if (seen[k]) return false; seen[k] = true; return true; })
  .sort(function (a, b) { return Date.parse(b.at) - Date.parse(a.at); });
const now = Date.now(), week = now - 7 * 86400000;
const count = function (fn) { return feed.filter(fn).length; };
const stats = {
  total: feed.length,
  this_week: count(function (a) { return Date.parse(a.at) >= week; }),
  appointments: count(function (a) { return a.type === 'appointment' && a.status !== 'cancelled' && a.status !== 'rescheduled'; }),
  upcoming: count(function (a) { return a.type === 'appointment' && Date.parse(a.when) >= now && a.status !== 'cancelled' && a.status !== 'rescheduled'; }),
  open_tickets: count(function (a) { return a.type === 'ticket' && ['resolved', 'closed'].indexOf(a.status) < 0; }),
  transfers: count(function (a) { return a.type === 'transfer'; }),
  pending_callbacks: count(function (a) { return a.type === 'callback' && ['done', 'completed', 'called'].indexOf(a.status) < 0; })
};
const pick = $('Pick Client Sheet').first().json;
return [{ json: { ok: true, business: who.business || pick.client_name || '', email: who.email, generated_at: new Date().toISOString(),
  sheet_found: pick.sheet_id !== 'missing', stats: stats, activity: feed.slice(0, 250) } }];
